"""Synthetic durable runner process. Never connects to product APIs."""
import argparse
import json
import os
from pathlib import Path

parser=argparse.ArgumentParser()
parser.add_argument('root');parser.add_argument('action',choices=['submit','reconcile','cancel']);parser.add_argument('operation_id');parser.add_argument('--input-hash',default='synthetic');parser.add_argument('--crash-after-effect',action='store_true')
args=parser.parse_args()
root=Path(args.root);root.mkdir(parents=True,exist_ok=True)
# IDs in this fixture are generated by tests, with no arbitrary paths accepted.
if not args.operation_id.replace('-','').isalnum(): raise ValueError('invalid fixture operation ID')
record=root/(args.operation_id+'.json')
if args.action=='submit':
    try:
        fd=os.open(record,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
    except FileExistsError:
        data=json.loads(record.read_text())
        if data['input_hash']!=args.input_hash: raise ValueError('operation input changed')
    else:
        data={'operation_id':args.operation_id,'input_hash':args.input_hash,'starts':1,'accepted':True,'completed':False,'resources':[args.operation_id+'-resource'],'cancelled':False,'fixture':'synthetic'}
        with os.fdopen(fd,'w') as stream:
            json.dump(data,stream);stream.flush();os.fsync(stream.fileno())
    if args.crash_after_effect: os._exit(71)
    print(json.dumps(data))
elif args.action=='reconcile':
    print(record.read_text() if record.exists() else json.dumps({'state':'not_submitted','authoritative':True}))
else:
    data=json.loads(record.read_text());data['cancelled']=True
    stage=root/(args.operation_id+'.tmp')
    with stage.open('w') as stream:
        json.dump(data,stream);stream.flush();os.fsync(stream.fileno())
    os.replace(stage,record)
    print(json.dumps(data))
